public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this MassMomentOfInertia value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this MassMomentOfInertia value) => new(Math.Sqrt(value.SI));

    public static MassMomentOfInertia Sum(this IEnumerable<MassMomentOfInertia> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return MassMomentOfInertia.FromSI(sum);
    }

    public static MassMomentOfInertia Average(this IEnumerable<MassMomentOfInertia> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : MassMomentOfInertia.FromSI(sum / count);
    }

    public static MassMomentOfInertia Min(this IEnumerable<MassMomentOfInertia> values) => Aggregate(values, Math.Min);
    public static MassMomentOfInertia Max(this IEnumerable<MassMomentOfInertia> values) => Aggregate(values, Math.Max);

    private static MassMomentOfInertia Aggregate(IEnumerable<MassMomentOfInertia> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return MassMomentOfInertia.FromSI(result);
    }
}
